 'tr-today':['THREE RIVERS','Today'],'tr-active':['THREE RIVERS','Active Accounts'],'tr-pipeline':['THREE RIVERS','Pipeline'],'tr-tasks':['THREE RIVERS','Tasks'],'tr-route':['THREE RIVERS','Route'],'tr-panels':['THREE RIVERS','Panels & Codes'],'tr-payors':['THREE RIVERS','Payors']
